function isFallbackEligibleProfileFailure(reason:ProfileFetchFailureReason|undefined){return reason==="HTTP_403"||reason==="HTTP_429"||reason==="HTTP_5XX"||reason==="TIMEOUT"||reason==="CONNECTION_FAILURE"||reason==="TLS_FAILURE"||reason==="CONTENT_TYPE_REJECTED"||reason==="RESPONSE_TOO_LARGE"||reason==="EMPTY_RESPONSE"||reason==="ANTI_BOT"||reason==="INTERSTITIAL"||reason==="HTTP_OTHER";} function classifyFetchFailure(result:FetchResult){if(result.reason)return result.reason;if(result.timedOut)return"TIMEOUT";if(result.status===403)return"HTTP_403";if(result.status===429)return"HTTP_429";if((result.status??0)>=500)return"HTTP_5XX";if((result.status??0)>=400)return"HTTP_OTHER";if(result.status===undefined)return"UNKNOWN_FAILURE";return"EMPTY_RESPONSE";} function classifyThrownFetchError(error:unknown):ProfileFetchFailureReason{const message=error instanceof Error?error.message.toLowerCase():String(error).toLowerCase();if(/dns|getaddrinfo|enotfound|eai_again|eai_fail/.test(message))return"DNS_FAILURE";if(/tls|certificate|ssl|cert_/.test(message))return"TLS_FAILURE";if(/timeout|timed out|abort/.test(message))return"TIMEOUT";if(/connect|socket|econn|enetunreach|ehostunreach/.test(message))return"CONNECTION_FAILURE";return"UNKNOWN_FAILURE";} function isInfrastructurePage(text:string,source:SourceId){if(INFRASTRUCTURE_PAGE.test(text))return true;const lower=text.toLowerCase();return source.endsWith("-jina")&&/forbidden|access denied|rate limit|blocked|captcha/.test(lower)&&text.length<5000;}
